arguments.command:
RAILS_ENV=test bundle exec rails runner '
  book = Book.first || Book.create!(title: "Test Book", slug: "test-book", published: true)
  user = User.first || User.create!(name: "Test", email_address: "t@example.com", password: "secret")
  puts "Book: #{book.inspect}"
  puts "book.updated_at class: #{book.updated_at.class}"
  puts "book.last_edited_at: #{book.last_edited_at.inspect} (#{book.last_edited_at.class})"

  checks = {
    "1. Books::ReportsHelper#report_stamp" => -> {
      Object.new.extend(Books::ReportsHelper).report_stamp(book.updated_at)
    },
    "2. Book#report_summary" => -> {
      book.report_summary
    },
    "3. Books::ReportsController#card_filename" => -> {
      ctrl = Books::ReportsController.new
      ctrl.instance_variable_set(:@book, book)
      ctrl.send(:card_filename)
    },
    "4. Publishing::ReportCard#to_text" => -> {
      Publishing::ReportCard.new(book).to_text
    },
    "5. Publishing::ReportCard#covers_line" => -> {
      Publishing::ReportCard.new(book).send(:covers_line)
    },
    "6. ReportDigestMailer.weekly" => -> {
      book.update_column(:published, true) unless book.published?
      ReportDigestMailer.weekly(user).body.decoded
    },
    "7. ReportArchiveJob#header" => -> {
      ReportArchiveJob.new.send(:header, book)
    }
  }

  checks.each do |name, fn|
    begin
      res = fn.call
      puts "[OK] #{name} => #{res.inspect}"
    rescue => e
      puts "[FAIL] #{name} => #{e.class}: #{e.message}"
    end
  end
'

